#!/bin/bash
# Self-contained repro. Cases a, b (proj/a, proj/b) and c (generated by gen_c.py: 1200-module project with
# a >64 KiB aggregator import block) run through the OFFICIAL flow (lake build 4.33.1 + official lean4export + lake comparator
# 4.36) and the FAST flow (fastverify/pipeline/pipeline.sh + pchk run.sh). Case c needs ~32 cores and ~10 min:
#   env EVAL_THREADS=32 ./repro.sh      (32 CPUs; set CASES="a b" to skip c)
D=$(cd "$(dirname "$0")" && pwd); W=${1:-${TMPDIR:-/tmp}/$USER-repro-034}
rm -rf "$W"; mkdir -p "$W"; cp -a "$D/challenge" "$W/challenge"; S=""
for c in ${CASES:-a b c}; do
  if [ $c = c ]; then python3 -I "$D/gen_c.py" "$W/c"; else cp -a "$D/proj/$c" "$W/$c"; fi
  echo "######## case $c"
  bash "$D/officialflow.sh" "$W/$c" "$W/official-$c" "$W/challenge"; orc=$?
  bash "$D/fastflow.sh" "$W/$c" "$W/fast-$c" "$W/challenge/challenge.export"; frc=$?
  [ $c = c ] && python3 -c "import json,sys; d=json.load(open(sys.argv[1])); print('case c: prep deps of All:', len(d['All'][1]), 'of 1201; Slow included:', 'GeneratedComponents.Slow' in d['All'][1])" "$W/fast-c/run/log/deps.json"
  S="$S case $c: official_rc=$orc fast_rc=$frc;"
done
echo "=== SUMMARY$S (0 = ACCEPTED)"
